function openModal(title,body,footer='',large=false){const root=$('#modalRoot');root.innerHTML=`<div class="modal-backdrop"><section class="modal ${large?'large':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><div><h2>${esc(title)}</h2></div><button type="button" class="modal-close" data-modal-close aria-label="Close">×</button></div>${body}${footer?`<div class="modal-footer">${footer}</div>`:''}</section></div>`;const panel=root.querySelector('.modal');if(panel){['pointerdown','touchstart','click'].forEach(type=>panel.addEventListener(type,e=>e.stopPropagation()));}root.querySelectorAll('[data-modal-close]').forEach(el=>el.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();closeModal();}));const first=root.querySelector('input:not([type="hidden"]),select,textarea,button');if(first&&typeof first.focus==='function')setTimeout(()=>{try{first.focus({preventScroll:true})}catch(_){try{first.focus()}catch(__){}}},0);}
