const PROCESS_DEV_GATES=[['need','Need identified'],['plan','Development plan'],['trial','Trial / experiment'],['parameters','Parameters defined'],['risk','Risk review'],['measurement','Measurement / characterisation'],['capability','Capability / fitness'],['controlPlan','Control Plan impact'],['workInstruction','Work instruction'],['approval','Independent / required approval'],['release','Release process']];
const PROCESS_DEV_GUIDANCE={
 need:{action:'Confirm exactly why the released process cannot be used as-is and define the requested operating envelope.',evidence:'Request requirement plus the documented fit-gap assessment.',done:'The adaptation/new-process need and affected process envelope are explicitly documented.'},
 plan:{action:'Define the development approach, responsible engineer, expected effort, trial sequence and decision criteria.',evidence:'Development plan, owner, planned trials and planning allowance.',done:'The development plan is sufficient to schedule the development work.'},
 trial:{action:'Run or review representative trials for the changed geometry/material/parameter envelope.',evidence:'Trial ID(s), material, equipment, operator, parameter set, result and observations.',done:'At least one representative trial has been recorded and its outcome is understood.'},
 parameters:{action:'Define the proposed controlled parameter window and any limits or setup conditions.',evidence:'Parameter set / setup definition with rationale or reference.',done:'The intended process settings and boundaries are explicit rather than tribal knowledge.'},
 risk:{action:'Review failure modes created or changed by the new geometry and define prevention/detection controls.',evidence:'Linked process-risk review (PFMEA-style item), actions and residual-risk conclusion.',done:'Relevant risks are reviewed and high-risk items have an owner and control/action.'},
 measurement:{action:'Measure the trial output against the engineering requirement and capture objective characterisation.',evidence:'Measurement results, method, equipment/certificate and acceptance conclusion.',done:'The proposed process has objective result evidence rather than only visual judgement.'},
 capability:{action:'Decide whether the demonstrated process is fit for this build purpose and define any limitations.',evidence:'Fitness/capability conclusion and permitted envelope.',done:'The process is accepted for the intended prototype assurance level, or limitations are recorded.'},
 controlPlan:{action:'Update the Control Plan when the selected assurance level/special characteristics require one.',evidence:'Control Plan revision/characteristic linkage, or documented N/A rationale for this build purpose.',done:'Required controls are reflected in the controlled build documentation.'},
 workInstruction:{action:'Create or update the technician-facing work instruction for the released parameter set.',evidence:'Work-instruction ID/revision with execution steps and required evidence.',done:'A technician can execute the process without guessing the method.'},
 approval:{action:'Obtain the independent or role-based approval required by the selected build purpose/customer profile.',evidence:'Approver, role, timestamp and decision.',done:'Required approval is recorded and separation of duties is satisfied where configured.'},
 release:{action:'Release the developed process revision for controlled use in this build.',evidence:'Released process ID/revision, approval and revision history.',done:'The route references a released process revision and the process-development blocker is cleared.'}
};
