 const collect=()=>{if(step===0){draft.family=$('#pmFamily')?.value.trim()||draft.family;draft.partNumber=$('#pmPart')?.value.trim()||draft.partNumber;draft.revision=$('#pmRev')?.value.trim()||draft.revision;draft.hw=$('#pmHw')?.value.trim()||draft.hw;draft.sw=$('#pmSw')?.value.trim()||draft.sw;draft.safety=!!$('#pmSafety')?.checked;}else if(step===1){draft.bom=$$('[data-pm-bom-row]').map((row,i)=>({id:row.dataset.id||`BOM-${draft.id}-${i+1}`,kind:row.querySelector('[data-bom-kind]')?.value||'component',partNumber:row.querySelector('[data-bom-part]')?.value.trim(),description:row.querySelector('[data-bom-desc]')?.value.trim(),revision:row.querySelector('[data-bom-rev]')?.value.trim()||'A',qtyPerUnit:Number(row.querySelector('[data-bom-qty]')?.value||1),unit:row.querySelector('[data-bom-unit]')?.value.trim()||'pcs',unitCost:Number(row.querySelector('[data-bom-cost]')?.value||0),wastePct:Number(row.querySelector('[data-bom-waste]')?.value||0),basis:'unit'})).filter(x=>x.partNumber&&x.description);}else if(step===2){draft.defaultRoute=$$('[data-pm-route-row]').map(row=>row.querySelector('select')?.value).filter(Boolean);}};
 const bomRows=()=>draft.bom.map((b,i)=>`<div class="product-bom-edit-row" data-pm-bom-row data-id="${esc(b.id||'')}"><select data-bom-kind><option value="component" ${String(b.kind||'component').toLowerCase()!=='consumable'?'selected':''}>Component</option><option value="consumable" ${String(b.kind||'component').toLowerCase()==='consumable'?'selected':''}>Consumable</option></select><input data-bom-part placeholder="Part number" value="${esc(b.partNumber||'')}"><input data-bom-desc placeholder="Description" value="${esc(b.description||'')}"><input data-bom-rev placeholder="Rev" value="${esc(b.revision||'A')}"><input data-bom-qty type="number" min="0.001" step="0.001" value="${Number(b.qtyPerUnit||1)}"><input data-bom-unit placeholder="Unit" value="${esc(b.unit||'pcs')}"><input data-bom-cost type="number" min="0" step="any" value="${Number(b.unitCost||0)}"><input data-bom-waste type="number" min="0" step="any" value="${Number(b.wastePct||0)}"><button type="button" class="button tiny danger" data-remove-bom="${i}">×</button></div>`).join('');
