function careDueBand(x){const d=Number(x.daysToDue);if(x.status==='Scheduled')return 'Scheduled';if(d<0)return 'Overdue';if(d<=14)return 'Due ≤14 d';if(d<=30)return 'Due ≤30 d';if(d<=60)return 'Due ≤60 d';if(d<=90)return 'Due ≤90 d';return 'Later'}
function careDueVisual(x){const band=careDueBand(x),cls=band==='Overdue'?'bad':band==='Due ≤14 d'?'bad':/≤30|≤60/.test(band)?'warn':band==='Scheduled'?'good':'info';return `<span class="care-due ${cls}">${band==='Scheduled'?'✓':band==='Overdue'?'✕':'●'} ${esc(band)}</span>`}
function careGroupKey(x,mode){if(mode==='activity')return x.type;if(mode==='equipmentType')return x.equipmentType||'Other equipment';if(mode==='capability')return x.capability||'Other capability';if(mode==='competency')return x.skillName||'Other competency';if(mode==='person')return x.personName||x.targetName||'Other person';return x.targetName||'Individual items'}
function careGroupLabel(mode){return ({activity:'Activity type',equipmentType:'Equipment type',capability:'Equipment capability',competency:'Competency',person:'Person',individual:'Individual'})[mode]||'Group'}
function careNextUse(x){return x.nextUseStart?`${P.formatDateTime(x.nextUseStart)}${x.nextUseRequestId?` · ${esc(x.nextUseRequestId)}`:''}`:'No committed use in horizon'}
function carePlanTable(items){return `<div class="table-wrap"><table class="data-table care-table care-select-table"><thead><tr><th class="care-check-col"></th><th>Target</th><th>Due / expiry</th><th>Next committed use</th><th>System suggestion</th><th>Current reservation</th><th>Status</th><th></th></tr></thead><tbody>${items.map(x=>`<tr class="care-row ${x.status==='Overdue'?'care-overdue':''}" data-care-row="${esc(x.id)}"><td><input type="checkbox" aria-label="Select ${esc(x.targetName)}" data-care-select="${esc(x.id)}"></td><td><strong>${esc(x.targetName)}</strong><br><small>${esc(x.type)}${x.capability?` · ${esc(x.capability)}`:''}${x.skillName?` · ${esc(x.skillName)}`:''}</small></td><td><strong>${P.formatDate(x.dueDate)}</strong><br>${careDueVisual(x)}</td><td><small>${careNextUse(x)}</small></td><td><strong>${P.formatDateTime(x.recommendedStart)}</strong><br><small>${Number(x.durationHours).toFixed(1)} h · ${Number(x.loadHours).toFixed(1)}/${Number(x.capacityHours).toFixed(0)} h forecast load</small></td><td>${x.scheduledStart?`<strong>${P.formatDateTime(x.scheduledStart)}</strong><br><small>User-controlled reservation</small>`:'<span class="muted">Not scheduled</span>'}</td><td>${status(x.status)}</td><td><div class="route-toolbar care-actions">${btn(x.scheduledStart?'Change date':'Review & schedule',`data-schedule-care="${esc(x.id)}"`,'button tiny primary')}${x.scheduledStart?btn('Unschedule',`data-unschedule-care="${esc(x.itemKey)}"`,'button tiny secondary'):''}</div></td></tr>`).join('')||'<tr><td colspan="8">Nothing matches these filters.</td></tr>'}</tbody></table></div>`}
function careGroupedBoard(items,groupMode){if(groupMode==='individual')return `<div class="card">${carePlanTable(items)}</div>`;const groups={};items.forEach(x=>{const k=careGroupKey(x,groupMode);(groups[k]||(groups[k]=[])).push(x)});return `<div class="section-stack">${Object.entries(groups).sort((a,b)=>a[0].localeCompare(b[0])).map(([k,rows])=>`<div class="card care-group-card"><div class="section-title-row"><div><span class="eyebrow">${esc(careGroupLabel(groupMode).toUpperCase())}</span><h2>${esc(k)}</h2></div><div class="care-group-summary"><span class="pill">${rows.length} due item${rows.length===1?'':'s'}</span><span class="pill">${rows.filter(x=>x.status==='Overdue').length} overdue</span></div></div>${carePlanTable(rows)}</div>`).join('')}</div>`}
