 w.document.open();w.document.write(`<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><base href="${base}"><title>${esc(title)}</title><link rel="stylesheet" href="styles.css?v=1.0.35"><style>html,body{margin:0;background:#fff}body{padding:0}.print-document-shell{max-width:100%;margin:0 auto}</style></head><body class="print-build-report-document"><main class="print-document-shell">${clone.outerHTML}</main><script>(function(){function go(){var imgs=[].slice.call(document.images||[]);Promise.all(imgs.map(function(i){return i.complete?Promise.resolve():new Promise(function(r){i.addEventListener('load',r,{once:true});i.addEventListener('error',r,{once:true})})})).then(function(){setTimeout(function(){window.focus();window.print()},250)})}if(document.readyState==='complete')go();else window.addEventListener('load',go,{once:true})})();<\/script></body></html>`);w.document.close();
